sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var when = new GlideDateTime();
    var delay = new GlideTime();
    delay.setValue("00:00:01");
    when.add(delay); 
    var currentTime = new GlideDateTime();
    while (currentTime.getNumericValue() < when.getNumericValue()) { 
        currentTime = new GlideDateTime();
    }


    var totalCount = 0;
    var sucCount = 0;
    var failCount = 0;
    var reasonPdf = "";
    var errorReason = "";
    var excelReason = "";

    if (current.requirement_upload.nil()) {
        gs.info('No attachment uploaded. Skipping processing for record: ' + current.sys_id);
        return;
    }

    // Fetch the latest attachment for the record
    var attachmentGR = new GlideRecord('sys_attachment');
    attachmentGR.addQuery('sys_id', current.requirement_upload);
    attachmentGR.query();

    if (attachmentGR.next()) {
        var attachmentSysId = attachmentGR.sys_id;

        try {
            // Retrieve attachment content
            var attachment = new GlideSysAttachment();
            var contentStream = attachment.getContentStream(attachmentSysId);
            var parser = new sn_impex.GlideExcelParser();
            parser.setSource(contentStream);

            var sheetNames = parser.getSheetNames();
            var processedSheets = 0; // Counter for successful sheets

            // Iterate over each worksheet in the Excel workbook
            for (var i = 0; i < sheetNames.length; i++) {
                parser.setSheetName(sheetNames[i]);

                if (parser.parse()) {
                    var headers = parser.getColumnHeaders();

                    var content = buildCsv(headers, parser);
                    var newCsv = content.csv;

                    var fileName = "";

                    var sysAtt = new GlideRecord("sys_attachment");
                    sysAtt.addQuery("table_name", "ZZYYx_rptp_kotak_upload_excel");
                    sysAtt.addQuery("table_sys_id", current.sys_id);
                    sysAtt.query();

                    if (sysAtt.next()) {
                        fileName = sysAtt.getValue("file_name");
                    }

                    // Attach processed CSV
                    var grAttachment = new GlideSysAttachment();
                    grAttachment.write(current, fileName + '-Job ID ' + current.number + '.csv', 'text/csv', newCsv);
                    //gs.info("CSV file successfully attached to record: " + current.sys_id);

                    processedSheets++; // Increment counter for successful processing
                } else {
                    gs.addErrorMessage('Error parsing sheet: ' + sheetNames[i] + ' - ' + parser.getErrorMessage());
                }
            }

            parser.close();
        } catch (error) {
            gs.addErrorMessage('Error processing attachment: ' + error.message);
            parser.close();
        }
    } else {
        gs.addErrorMessage('No attachment found for record: ' + current.sys_id);
    }


    /**
     * Build CSV and PDF content from headers and parser rows.
     */
    function buildCsv(headers, parser) {
        // Initialize CSV content
        var csvContent = headers.join(',') + ',Status' + ',ErrorMessage\r\n';

        while (parser.next()) {
            var row = parser.getRow();

            // Check if row is empty
            var isEmptyRow = true;
            for (var i = 0; i < headers.length; i++) {
                var value = (row[headers[i]] || '').toString().trim();
                if (value !== '') {
                    isEmptyRow = false;
                    break;
                }
            }

            // If row is empty, add it to CSV with empty status and continue
            if (isEmptyRow) {
                //csvContent += headers.map(() => '').join(',') + ',EMPTY,-\r\n';
                continue;
            }

            var updateStatus = updateCase(row, headers).updated ? "SUCCESS" : "FAILURE";
            var excelError = updateCase(row, headers).error_message_excel || '-';
            var errorMessage = updateCase(row, headers).error_message || "-";

            // Add row to CSV
            csvContent += headers.map(header => (row[header] || '')).join(',') + ',' + updateStatus + ',' + excelError + '\r\n';

            totalCount++;
            if (updateStatus == "SUCCESS") {
                sucCount++;
            } else {
                failCount++;
            }
            if (errorMessage != "-") {

                reasonPdf += failCount + ". Loan Number - " + row[headers[3]] + ", Policy Number - " + row[headers[0]] + ", Member Dependent Number - " + row[headers[2]] + ", for the requirement ID - " + row[headers[7]] + ", has not been updated,\n\n<div style='color:red;'>Error Message:</div>" + errorMessage + "\n";

                errorReason += failCount + ". Loan Number - " + row[headers[3]] + ", Policy Number - " + row[headers[0]] + ", Member Dependent Number - " + row[headers[2]] + ", for the requirement ID - " + row[headers[7]] + ", has not been updated,\n\nError Message:\n" + errorMessage + "\n";
            }

        }

        return {
            csv: csvContent
        };
    }

    //Calling Subflow
    function updateCase(row, headers) {
        try {
            var inputs = {};
            inputs['medical_center_tpa_code'] = row[headers[5]];
            inputs['medical_center_tpa_name'] = row[headers[6]];
            inputs['requirement_received_date'] = row[headers[9]];
            inputs['requirement_upload_date'] = row[headers[10]];
            inputs['home_center_visit'] = row[headers[11]];
            inputs['loan_number'] = row[headers[3]];
            inputs['member_dependent_number'] = row[headers[2]];
            inputs['policy_number'] = row[headers[0]];
            inputs['requirement_code'] = row[headers[7]];
            inputs['requirement_status'] = row[headers[8]];

            // Execute Synchronously: Run in foreground. Code snippet has access to outputs.
            var result = sn_fd.FlowAPI.getRunner().subflow('x_rptp_kotak.kotak__updating_requirement_status').inForeground().withInputs(inputs).run();
            var outputs = result.getOutputs();

            // Get Outputs:
            var error_message_excel = outputs['error_message_excel']; // String
            var error_message = outputs['error_message']; // String
            var updated = outputs['updated']; // True/False

            return outputs;

        } catch (ex) {
            var message = ex.getMessage();
            gs.error(message);
        }


    }

    //updating the Record
    current.count_of_total_uploads = totalCount;
    current.successful = sucCount;
    current.failed = failCount;
    current.error_reason = errorReason;
    current.reason = reasonPdf;
    current.update();

    try {
        new x_rptp_kotak.pdf_kotak_uw_portal().job_id_pdf(current.sys_id);
    } catch (e) {
        gs.info(e);
    }

    try {
        gs.eventQueue("x_rptp_kotak.job_id_email", current);
    } catch (e) {
        gs.info(e);
    }


})(current, previous);
